export function ActiveState({
  label = "{{label}}",
  accent = "{{accent}}",
  force = {{force}},
  radius = {{radius}},
}) {
  return (
    <div style={{ width: 280, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, textAlign: "center" }}>
      <button
        type="button"
        style={{
          font: "700 15px system-ui, sans-serif", padding: "12px 24px", borderRadius: radius,
          border: `2px solid ${accent}`, background: accent, color: "#241430", cursor: "pointer",
          transform: force ? "translateY(4px)" : "translateY(0)",
          boxShadow: force ? "none" : `0 4px 0 color-mix(in srgb, ${accent} 60%, #241430)`,
        }}
      >
        {label}
      </button>
      <p style={{ margin: "14px 0 0", fontSize: 11, color: "#241430888" }}><strong>real :active</strong> click and hold the button · <strong>forced</strong> the toggle prop</p>
    </div>
  );
}
